import ast,base64,hashlib,json,copy
d=json.loads(base64.b64decode(""))
checks=[]
def ck(name,truth):
    if not truth: raise AssertionError(name)
    checks.append(name)
before,after=d["before"],d["after"]
a,b=ast.parse(before),ast.parse(after)
dump=lambda x:ast.dump(x,include_attributes=False)
assigns=lambda m:{n.targets[0].id:n for n in m.body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
aa,bb=assigns(a),assigns(b)
ck("same_top_level_AST_statement_count",len(a.body)==len(b.body))
ck("same_top_level_assignment_names",set(aa)==set(bb))
ck("old_unbound_ready_false_new_exact_true",ast.literal_eval(aa["ACTUAL_INPUTS_READY"].value) is False and ast.literal_eval(bb["ACTUAL_INPUTS_READY"].value) is True)
source=ast.literal_eval(bb["SOURCE_FILES"].value)
ck("two_source_rows_exact_root174_admitted",source==d["source_files"])
dest=[]
for i,raw in enumerate(d["destination_infos"]):
    inf=json.loads(raw)
    ck("destination%d_actual_info_metadata"%i,inf["mode"]==256 and inf["metadata"]["uid"]==1000 and inf["metadata"]["gid"]==1000 and inf["metadata"]["mode"]==256 and inf["metadata"]["link_count"]==1)
    dest.append(dict(name=source[i]["name"],path=inf["path"],bytes=inf["size"],sha256=inf["sha256"],mode=inf["mode"],version=inf["version"]))
ck("two_destination_rows_exact_independent_infos",ast.literal_eval(bb["FILES"].value)==dest)
ti=json.loads(d["transfer_info"])
transfer=dict(name="source-carrier.result.public.json",path=ti["path"],bytes=ti["size"],sha256=ti["sha256"],mode=ti["mode"],version=ti["version"])
ck("transfer_info_metadata",ti["mode"]==384 and ti["metadata"]["uid"]==1000 and ti["metadata"]["gid"]==1000 and ti["metadata"]["link_count"]==1)
ck("transfer_row_exact_whole_core_info",ast.literal_eval(bb["TRANSFER"].value)==transfer)
changed=0
for key in ["SOURCE_FILES","FILES","TRANSFER"]:
    old=ast.literal_eval(aa[key].value);new=ast.literal_eval(bb[key].value)
    olds=old if isinstance(old,list) else [old];news=new if isinstance(new,list) else [new]
    ck(key+"_same_row_count",len(olds)==len(news))
    for i,(x,y) in enumerate(zip(olds,news)):
        ck(key+str(i)+"_same_fields",set(x)==set(y))
        ck(key+str(i)+"_only_three_nulls_become_pins",all(x[k] is None and y[k] is not None for k in ["bytes","sha256","version"]) and all(x[k]==y[k] for k in x if k not in ["bytes","sha256","version"]))
        changed+=3
ck("15_input_literals",changed==15)
defs=lambda m:{n.name:n for n in m.body if isinstance(n,(ast.FunctionDef,ast.ClassDef,ast.AsyncFunctionDef))}
ad,bd=defs(a),defs(b)
ck("same_definition_names",set(ad)==set(bd))
for name in ad:
    if name!="verify_receipts":
        ck(name+"_complete_definition_byte_identical",ast.get_source_segment(before,ad[name])==ast.get_source_segment(after,bd[name]))
guards={
"transported['controller']['bytes']":d["helper_pins"]["controller_bytes"],
"transported['controller']['sha256']":d["helper_pins"]["controller_sha256"],
"transported['helpers']['sender.py']['sha256']":d["helper_pins"]["sender_sha256"],
"transported['helpers']['receiver.py']['sha256']":d["helper_pins"]["receiver_sha256"]}
patched=copy.deepcopy(b)
for n in patched.body:
    if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id in ["ACTUAL_INPUTS_READY","SOURCE_FILES","FILES","TRANSFER"]:
        n.value=copy.deepcopy(aa[n.targets[0].id].value)
changed_guards=[]
for n in ast.walk(next(n for n in patched.body if isinstance(n,ast.FunctionDef) and n.name=="verify_receipts")):
    if isinstance(n,ast.Compare) and ast.unparse(n.left) in guards:
        key=ast.unparse(n.left)
        ck(key+"_only_expected_literal",len(n.ops)==1 and isinstance(n.ops[0],ast.Eq) and len(n.comparators)==1 and isinstance(n.comparators[0],ast.Constant) and n.comparators[0].value==guards[key])
        old=[x for x in ast.walk(ad["verify_receipts"]) if isinstance(x,ast.Compare) and ast.unparse(x.left)==key]
        ck(key+"_original_single_None_guard",len(old)==1 and len(old[0].comparators)==1 and isinstance(old[0].comparators[0],ast.Constant) and old[0].comparators[0].value is None)
        n.comparators=[ast.Constant(value=None)]
        changed_guards.append(key)
ck("exact_four_receipt_literal_bindings",len(changed_guards)==4 and set(changed_guards)==set(guards))
ck("full_AST_identical_after_exact20_literal_reversal",dump(patched)==dump(a))
ta=[n for n in a.body if isinstance(n,ast.Try)];tb=[n for n in b.body if isinstance(n,ast.Try)]
ck("complete_original_main_try_byte_identical",len(ta)==len(tb)==1 and ast.get_source_segment(before,ta[0])==ast.get_source_segment(after,tb[0]))
ck("original_final_exit_byte_identical",ast.get_source_segment(before,a.body[-1])==ast.get_source_segment(after,b.body[-1]))
req=d["request_projection"];s=hashlib.sha256(after.encode()).hexdigest()
ck("request_exact_original_inline_shape",req["host"]=="desktop" and req["executable"]=="/usr/bin/python3" and req["cwd"]=="/home/qian-qi/heptabao-ha-closure-20261103-r1" and req["timeout_seconds"]==330 and len(req["args"])==6 and req["args"][:4]==["-I","-S","-B","-c"] and req["args"][5]==s)
ck("new_single_unsubmitted_key_bound_to_source",req["idempotency_key"]=="heptabao-4e808-standalone-source-import-"+s[:8]+"-20261105-r1")
ck("self_SHA_argument_matches_sys_orig_argv_slots",len([req["executable"]]+req["args"])==7 and ([req["executable"]]+req["args"])[6]==s)
ck("original300_60_90_and_64MiB_contract_unchanged",ast.literal_eval(bb["MAX_BUNDLE"].value)==67108864 if isinstance(bb["MAX_BUNDLE"].value,ast.Constant) else dump(bb["MAX_BUNDLE"])==dump(aa["MAX_BUNDLE"]))
print(json.dumps({"schema":"heptabao.root-source2-importer-actual-literal-binding-AST.r30.v1","status":"PASS_SOURCE_ONLY","checks_passed":len(checks),"checks":checks,"before_bytes":len(before.encode()),"after_bytes":len(after.encode()),"after_sha256":s,"changed_literals":20,"unchanged_definitions":len(ad)-1,"receipt_function_only_four_constants":True,"complete_main_try_byte_identical":True,"whole_request_pin":d["whole_request_pin"],"actual_custody_root_review":d["root_actual_transfer_review"],"candidate_executed":False,"candidate_definitions_called":False,"private_inputs_read":False,"Runtime_calls":0,"Git_import_executed":False},sort_keys=True))
